B.amK=new A.cq("\u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u0652\u062b\u064f","Min haitsu","QS. Al-Baqarah",'Nun sukun (\u0646\u0652) bertemu huruf Ha (\u062d), dibaca jelas "Min haitsu" tanpa berdengung.')
B.an1=new A.cq("\u0639\u064e\u0630\u064e\u0627\u0628\u064c \u0623\u064e\u0644\u0650\u064a\u0652\u0645\u064c","'Adzaabun aliim","QS. Al-Baqarah: 10",'Dhommatain bertemu huruf Hamzah/Alif (\u0623), dibaca jelas "-bun aliim".')
B.amF=new A.cq("\u0645\u064e\u0646\u0652 \u0622\u0645\u064e\u0646\u064e","Man aamana","QS. Al-Baqarah: 62",'Nun sukun bertemu huruf Alif (\u0621), dibaca terang "Man aamana".')
